/*
Program Name: SASZombieAssaultTD
File Path: Engine/UI/HUDManager.cs
Purpose: Central manager for HUD layout loading, rendering, and state management.
Features:
  - Manages HUD textures and layout from JSON configuration
  - Provides texture and text element dictionaries for efficient lookup
  - Maintains render order for layered HUD element display
  - Integrates with TextureManager for texture resource management
  - Supports button flash effects with configurable color and timing
  - Provides singleton pattern for global HUD manager access
  - Includes cash and lives button hitbox management
  - Loads HUD configuration from HUDConfigManager
*/

using SASZombieAssaultTD.Engine.Core;using SASZombieAssaultTD.Engine.Diagnostics;  using SASZombieAssaultTD.Engine.Core; using SASZombieAssaultTD.Engine.Input; using SASZombieAssaultTD.Engine.Player; using SASZombieAssaultTD.Engine.Rendering; using SASZombieAssaultTD.Engine.Snapshot; using System; using System.Collections.Generic; using System.IO; using System.Linq; using System.Text.Json;  // Resolve IRenderContext ambiguity using IRenderContext = SASZombieAssaultTD.Engine.Rendering.IRenderContext;  namespace SASZombieAssaultTD.Engine.UI {     public class HUDManager     {         private Resources.Texture2D _hudTexture;         private Resources.Texture2D _supportHUDTexture;          private HUDLayout _layout;         private readonly Dictionary<string, HUDTextureElement> _textureDict = new();         private readonly Dictionary<string, HUDTextElement> _textDict = new();         private readonly List<IHUDElement> _renderOrder = new();          private readonly TextureManager _textureManager;          // Cash / Lives button hitboxes - loaded from HUDConfigManager         private Rect cashPlusRect;          private Rect livesPlusRect;          // Button flash state         public System.Drawing.Color ButtonFlashColor = System.Drawing.Color.Crimson;          private float _buttonFlashTimer = 0f;         protected const float BUTTON_FLASH_TIME = 0.10f;          // Static reference         public static HUDManager Instance { get; private set; }          public HUDManager(TextureManager textureManager)         {             _textureManager = textureManager ?? throw new ArgumentNullException(nameof(textureManager));             Instance = this;         }          // 🎯 FIX: Provide access to the cash panel finalizer instance         public HUDPanel_Finalizer GetCashPanelFinalizer()         {             // Locate HUDPanel_Finalizer in render order             foreach (var element in _renderOrder)             {                 if (element is HUDPanel_Finalizer panel)                 {                     return panel;                 }             }              return null;         }          // ---------------------------------------------------------         // LOAD HUD         // ---------------------------------------------------------         public void Load(string jsonPath)         {             // Load hitbox values from HUDConfigManager (Finalizer JSON)             var cashPanel = HUDConfigManager.GetPanel("cash_panel");             if (cashPanel != null)             {                 // Center hitbox on crosshair position                 var crosshairX = cashPanel.crosshair?.centerX ?? 122;                 var crosshairY = cashPanel.crosshair?.centerY ?? 553;                 cashPlusRect = new Rect(                     crosshairX - 10,  // Center 20px wide hitbox on crosshair                     crosshairY - 10,  // Center 20px tall hitbox on crosshair                     20, 20                 );             }             else             {                 // Fallback defaults centered on default crosshair                 cashPlusRect = new Rect(112, 543, 20, 20);             }              var livesPanel = HUDConfigManager.GetPanel("lives_panel");             if (livesPanel != null)             {                 livesPlusRect = new Rect(                     livesPanel.x + livesPanel.width - 10,                     livesPanel.y + 5,                     10, 10                 );             }             else             {                 livesPlusRect = new Rect(230, 550, 10, 10);             }              var options = new JsonSerializerOptions { PropertyNameCaseInsensitive = true };              if (File.Exists(jsonPath))             {                 var json = File.ReadAllText(jsonPath);                  // DATA INTEGRITY DIAGNOSTICS                  _layout = JsonSerializer.Deserialize<HUDLayout>(json, options);                  if (_layout != null)                 {                     int imageCount = _layout.Images?.Count ?? 0;                     int textCount = _layout.Text?.Count ?? 0;                     int renderOrderCount = _layout.RenderOrder?.Count ?? 0;                 }                 else                 {                 }             }             else             {                 _layout = new HUDLayout();             }              // Load textures              // DATA INTEGRITY DIAGNOSTICS             int totalImages = _layout.Images?.Count ?? 0;              foreach (var tex in _layout.Images)             {                 _textureDict[tex.Id] = tex;                  string path = tex.Path;                  if (tex.Id == "hud_surface")                 {                     path = "Assets/UI/HUD.png";                 }                  if (tex.Id == "support_hud")                 {                     path = "Assets/UI/SupportHUD.png";                 }                  tex.Texture = _textureManager.Get(path);                  // 🎯 CRITICAL IMAGE LOADING VERIFICATION                 bool textureLoaded = tex.Texture != null;                  // Conditional checks for each specific image                 if (tex.Id == "map" || tex.Path.Contains("MeanStreets"))                 {                 }                 else if (tex.Id == "hud_surface" || tex.Path.Contains("HUD.png"))                 {                 }                 else if (tex.Id == "support_hud" || tex.Path.Contains("SupportHUD.png"))                 {                 }                  // DATA INTEGRITY DIAGNOSTICS                  if (tex.Id == "hud_surface")                 {                     _hudTexture = (Resources.Texture2D)tex.Texture;                 }                  if (tex.Id == "support_hud")                 {                     _supportHUDTexture = (Resources.Texture2D)tex.Texture;                 }             }              // Load text elements             foreach (var txt in _layout.Text)             {                 _textDict[txt.Id] = txt;                  if (txt.Id == "cash_text")                 {                     int playerCash = PlayerSystem.Instance?.State?.Cash ?? 0;                     txt.Value = playerCash.ToString();                 }                 else if (txt.Id == "lives_text")                 {                     int playerLives = PlayerSystem.Instance?.State?.Lives ?? 0;                     txt.Value = $"{playerLives}";                 }                 else if (txt.Id == "waves_text")                 {                     txt.Value = $"1/40";                 }             }             // ---------------------------------------------------------             // CREATE FINALIZER FIRST (Program 2 must exist before panels)             // ---------------------------------------------------------             var finalizer = new HUDPanel_Finalizer(this);              // Add Finalizer to render order BEFORE anything else             _renderOrder.Add(finalizer);              // Run manual entry processing BEFORE any HUDPanel_* draws             finalizer.ProcessEntryData();              // Build render order             _renderOrder.Clear();              if (_layout.RenderOrder != null && _layout.RenderOrder.Count > 0)             {                 foreach (var id in _layout.RenderOrder)                 {                     if (_textureDict.TryGetValue(id, out var tex))                     {                         _renderOrder.Add(tex);                     }                     else if (_textDict.TryGetValue(id, out var txt))                     {                         _renderOrder.Add(txt);                     }                     else                     {                     }                 }                  foreach (var tex in _layout.Images.Where(i => !_renderOrder.Contains(i)).OrderBy(i => i.Layer))                 {                     _renderOrder.Add(tex);                 }                  foreach (var txt in _layout.Text.Where(t => !_renderOrder.Contains(t)).OrderBy(t => t.Layer))                 {                     _renderOrder.Add(txt);                 }             }             else             {                 foreach (var tex in _layout.Images.OrderBy(i => i.Layer))                 {                     _renderOrder.Add(tex);                 }                  foreach (var txt in _layout.Text.OrderBy(t => t.Layer))                 {                     _renderOrder.Add(txt);                 }             }              _renderOrder.Insert(0, finalizer);             // ---------------------------------------------------------             // FINALIZER COLOR DISTRIBUTION (AFTER render order is built)             // ---------------------------------------------------------             DistributeFinalizerColors();         }          // ---------------------------------------------------------         // UPDATE HUD         // ---------------------------------------------------------         public void Update(float deltaTime)         {             // NULL PROPAGATION DIAGNOSTICS              try             {                 if (_buttonFlashTimer > 0)                 {                     _buttonFlashTimer -= deltaTime;                     if (_buttonFlashTimer <= 0)                     {                         ResetButtonFlash();                     }                 }                  bool click = InputSystem.IsMouseButtonJustPressed(0);                 var mouse = InputSystem.GetMousePosition();                 var mp = new System.Numerics.Vector2(mouse.X, mouse.Y);                  if (click)                 {                     if (cashPlusRect.Contains(mp))                     {                         PlayerSystem.Instance.State.Cash += 1;                         TriggerButtonFlash();                         SnapshotIntegration.EnsureTodaySnapshot();                     }                     else if (livesPlusRect.Contains(mp))                     {                         PlayerSystem.Instance.State.Lives += 1;                         TriggerButtonFlash();                         SnapshotIntegration.EnsureTodaySnapshot();                     }                     else                     {                     }                 }                  UpdateText("cash_text", $"${PlayerSystem.Instance.State.Cash}");                 UpdateText("lives_text", $"{PlayerSystem.Instance.State.Lives}");                 UpdateText("waves_text", "1/40");             }             catch (Exception ex)             {                 System.Diagnostics.Debug.WriteLine("Error", $"HUDManager: Update failed: {ex.Message}");                 throw;             }         }          // ---------------------------------------------------------         // DRAW HUD         // ---------------------------------------------------------         public void Draw(IRenderContext context, int crosshairCenterX = 0, int crosshairCenterY = 0)         {             // NULL PROPAGATION DIAGNOSTICS              // EXCEPTION-ADJACENT DIAGNOSTICS              try             {                 if (_layout == null)                 {                     return;                 }                  // Get crosshair configuration from HUDPanel_Finalizer if available                 HUDPanel_Finalizer cashPanel = null;                 foreach (var element in _renderOrder)                 {                     if (element is HUDPanel_Finalizer panel)                     {                         cashPanel = panel;                         break;                     }                 }                  // Use finalizer properties or fall back to defaults                 int cx = cashPanel?.CrosshairCenterX ?? crosshairCenterX;                 int cy = cashPanel?.CrosshairCenterY ?? crosshairCenterY;                 int armLength = cashPanel?.CrosshairArmLength ?? 8;                 int thickness = cashPanel?.CrosshairThickness ?? 2;                  // Determine crosshair color - use Finalizer color as base, flash only when active                 System.Drawing.Color crosshairColor;                 if (cashPanel != null)                 {                     // Use CrosshairColor as base, override with ButtonFlashColor only during flash                     crosshairColor = (_buttonFlashTimer > 0) ? ButtonFlashColor : cashPanel.CrosshairColor;                 }                 else                 {                     crosshairColor = ButtonFlashColor;                 }                  // Draw HUD elements first                 foreach (var element in _renderOrder)                 {                     try                     {                         element.Draw(context);                     }                     catch (Exception ex)                     {                     }                 }                  // ---------------------------------------------------------                 // DRAW CROSSHAIR LAST — ON TOP OF EVERYTHING                 // ---------------------------------------------------------                  var crossColor = new SASZombieAssaultTD.Engine.Core.Colorize.Color(                     crosshairColor.R / 255f,                     crosshairColor.G / 255f,                     crosshairColor.B / 255f,                     crosshairColor.A / 255f                 );                  // Horizontal bar                 int horizX = cx - armLength;                 int horizY = cy - thickness / 2;                 int horizW = armLength * 2;                 int horizH = thickness;                  // EXCEPTION-ADJACENT DIAGNOSTICS                  var horizRect = new Rectangle(horizX, horizY, horizW, horizH);                 context.FillRectangle(horizRect, crossColor);                  // Vertical bar                 int vertX = cx - thickness / 2;                 int vertY = cy - armLength;                 int vertW = thickness;                 int vertH = armLength * 2;                  // EXCEPTION-ADJACENT DIAGNOSTICS                  var vertRect = new Rectangle(vertX, vertY, vertW, vertH);                 context.FillRectangle(vertRect, crossColor);             }             catch (Exception ex)             {                 throw;             }         }          // ---------------------------------------------------------         // TEXT UPDATE HELPER         // ---------------------------------------------------------         public void UpdateText(string id, string newValue)         {             // NULL PROPAGATION DIAGNOSTICS              if (_textDict.TryGetValue(id, out var txt))             {                 if (txt.Value != newValue)                 {                     txt.Value = newValue;                 }             }             else             {             }         }          // ---------------------------------------------------------         // BUTTON FLASH API         // ---------------------------------------------------------         public virtual void TriggerButtonFlash()         {             // Get flash color from Finalizer if available             System.Drawing.Color flashColor = System.Drawing.Color.LightGreen; // default             foreach (var element in _renderOrder)             {                 if (element is HUDPanel_Finalizer panel)                 {                     flashColor = panel.FlashColor;                     break;                 }             }             ButtonFlashColor = flashColor;             _buttonFlashTimer = BUTTON_FLASH_TIME;         }          protected virtual void ResetButtonFlash()         {             // ButtonFlashColor will be overridden by CrosshairColor in Draw() when timer <= 0         }          // ---------------------------------------------------------         // FINALIZER COLOR DISTRIBUTION (PASS-THROUGH LOGIC)         // ---------------------------------------------------------          /// <summary>         /// Distributes Finalizer colors to all HUD panels.         /// HUDManager acts as pass-through component only.         /// No interpretation, modification, or fallback logic applied.         /// </summary>         private void DistributeFinalizerColors()         {             // Locate HUDPanel_Finalizer             HUDPanel_Finalizer finalizer = null;             foreach (var element in _renderOrder)             {                 if (element is HUDPanel_Finalizer panel)                 {                     finalizer = panel;                     break;                 }             }              if (finalizer == null)             {                 return;             }              // Diagnostics: Check Finalizer state before distribution              // Distribute colors to each HUDPanel_* instance             foreach (var element in _renderOrder)             {                 if (element is HUDPanel_Cash cashPanel)                 {                     finalizer.ApplyFinalizerColors(cashPanel);                 }                 // Additional HUDPanel_* types will be added here as they are implemented                 // Following the one-panel-at-a-time rule             }         }     } }
